#include <variant>
#include <iostream>

struct Shape {
  virtual double area() const = 0;
  virtual ~Shape() = default;
};

struct Circle : Shape {
  double radius;
  Circle(double r) : radius(r) {}
  double area() const override { return 3.14159 * radius * radius; }
};

struct Rectangle : Shape {
  double width, height;
  Rectangle(double w, double h) : width(w), height(h) {}
  double area() const override { return width * height; }
};

int main() {
  std::variant<Circle, Rectangle> shape1 = Circle(5.0);
  std::variant<Circle, Rectangle> shape2 = Rectangle(4.0, 6.0);

  // Compile-time polymorphism with std::visit
  double area1 = std::visit([](auto&& arg) -> double {
    using T = std::decay_t<decltype(arg)>;
    if constexpr (std::is_same_v<T, Circle>) {
      return arg.area();
    } else if constexpr (std::is_same_v<T, Rectangle>) {
      return arg.area();
    }
    return 0.0; //Should be unreachable
  }, shape1);

  //Runtime polymorphism with virtual functions
  Shape* shape3 = new Circle(5.0);
  double area3 = shape3->area();
  delete shape3;
  std::cout << area1 << " " << area3 << std::endl;
  return 0;
}
